def appliquer_ajouts(stock, operations):
    copie = stock.copy()
    for type_op, article, quantite in operations:
        if type_op == "ajout" and quantite > 0:
            copie[article] = copie.get(article, 0) + quantite
    return copie

def compter_invalides(operations):
    nombre = 0
    for type_op, article, quantite in operations:
        if type_op not in ["ajout", "retrait"] or quantite <= 0:
            nombre = nombre + 1
    return nombre

def appliquer_operations(stock, operations):
    copie = stock.copy()
    for type_op, article, quantite in operations:
        if quantite > 0:
            if type_op == "ajout":
                copie[article] = copie.get(article, 0) + quantite
            elif type_op == "retrait" and article in copie and copie[article] >= quantite:
                copie[article] = copie[article] - quantite
    return copie

def gerer_inventaire(stock, operations):
    copie = stock.copy()
    refus = 0
    for type_op, article, quantite in operations:
        accepte = False
        if quantite > 0:
            if type_op == "ajout":
                copie[article] = copie.get(article, 0) + quantite
                accepte = True
            elif type_op == "retrait" and article in copie and copie[article] >= quantite:
                copie[article] = copie[article] - quantite
                accepte = True
        if not accepte:
            refus = refus + 1
    return {"stock": copie, "refus": refus}
